import snapshot from './update-source.json' with {type:'json'};
export const updateSource=snapshot;
export type UpdateSourceId=keyof typeof snapshot.sources;
export type UpdateFocus={ref:UpdateSourceId;from:number;to:number};
export type UpdatePoint=UpdateFocus&{id:string;stage:string;title:string;method:string;why:string;effect?:'checkout'|'command'|'event'|'apply'|'persist'|'finish'|'return'|'view'|'paid-checkout'|'process-checkout'|'quote'|'objects'|'enqueue'|'consume'|'permission-quote';supports:UpdateSourceId[]};
export type UpdateQuestion={title:string;question:string;correct:string;wrong:string;feedback:string};
export type UpdateStep={id:string;title:string;situation:string;input:string;output:string;questions:UpdateQuestion[]};
export type UpdatePair={id:string;stage:string;from:string;to:string;label:string;a:UpdateFocus;b:UpdateFocus;kind?:'call'|'data'|'event';note?:string};
export type UpdateScenario={id:string;label:string;stopAt?:string;message?:string;kind?:'error'|'skip'};
export type UpdateFlow={id:string;title:string;entry:string;actor:string;identity:string;startLabel:string;entryKind:'http'|'queue';limits:string[];changed:string[];eventName:string;steps:UpdateStep[];points:UpdatePoint[];pairs:UpdatePair[];scenarios:UpdateScenario[]};
const q=(title:string,question:string,correct:string,wrong:string,feedback:string):UpdateQuestion=>({title,question,correct,wrong,feedback});
const p=(id:string,stage:string,title:string,ref:UpdateSourceId,from:number,to:number,method:string,why:string,effect?:UpdatePoint['effect'],supports:UpdateSourceId[]=[]):UpdatePoint=>({id,stage,title,ref,from,to,method,why,effect,supports});
const f=(ref:UpdateSourceId,from:number,to:number):UpdateFocus=>({ref,from,to});
const pair=(id:string,stage:string,from:string,to:string,label:string,a:UpdateFocus,b:UpdateFocus,kind:UpdatePair['kind']='call',note?:string):UpdatePair=>({id,stage,from,to,label,a,b,kind,note});
