export const updateFlows:UpdateFlow[]=[checkoutFlow,paidFlow,endorsementFlow,permissionFlow,migrationFlow,documentsFlow,correctFlow];
export function updateFlowFor(params:URLSearchParams){return updateFlows.find(f=>f.id===params.get('flow'))??updateFlows[0];}
export const updateKey=(flow:UpdateFlow|string,key:string)=>`u.${typeof flow==='string'?flow:flow.id}.${key}`;
